values ('bbbb0004-0000-4000-8000-00000000001b', 'en', null, 'The Immune System & Microbiology', 'How microbes cause disease and how the body fights back — from bacteria and viruses to innate barriers, B and T cells, vaccines, and antibiotic resistance. Structure adapted from OpenStax Microbiology (CC BY 4.0).', null, 'foundations', 27, true, 'science', '{bbbb0004-0000-4000-8000-000000000001}')
