insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000001b', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Which group of microbes are living cells with their own protein-making machinery?","options":["viruses","bacteria","prions","none of these"],"answer":1,"explanation":"Bacteria are living cells; viruses are not — see ''A tour of the microbes''."},{"prompt":"A virus can only reproduce by…","options":["dividing on its own","hijacking a host cell","absorbing nutrients from soil","photosynthesis"],"answer":1,"explanation":"Viruses have no metabolism of their own and must use a host cell — see ''A tour of the microbes''."},{"prompt":"Which is a physical barrier of innate immunity?","options":["antibodies","intact skin","memory T cells","vaccines"],"answer":1,"explanation":"Skin is a first-line barrier — see ''Innate immunity''."},{"prompt":"Redness, heat, swelling, and pain at a wound are signs of…","options":["adaptive memory","inflammation","antibiotic resistance","vaccination"],"answer":1,"explanation":"The four classic signs of inflammation — see ''Innate immunity''."},{"prompt":"Antibodies are produced by…","options":["red blood cells","B cells (plasma cells)","skin cells","viruses"],"answer":1,"explanation":"Activated B cells become antibody-secreting plasma cells — see ''Adaptive immunity''."},{"prompt":"The reason a second exposure to a pathogen is often fought off faster is…","options":["the pathogen weakens","immunological memory","antibiotics build up","the skin thickens"],"answer":1,"explanation":"Memory cells respond quickly on re-exposure — see ''Vaccines and immune memory''."},{"prompt":"A vaccine works mainly by…","options":["killing microbes directly in the blood","training the immune system before real infection","replacing white blood cells","sterilizing the gut"],"answer":1,"explanation":"Vaccines prime memory without causing the disease — see ''Vaccines and immune memory''."},{"prompt":"Antibiotics are effective against…","options":["viruses like the common cold","bacteria","all microbes equally","human cells"],"answer":1,"explanation":"Antibiotics target bacterial structures, not viruses — see the diagnostic and later lessons."}]}'::jsonb, null, 10),
  (2, 'A tour of the microbes: bacteria, viruses, and fungi', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the main groups of microbes and explain why viruses are treated differently from bacteria and fungi. Warm-up: from the diagnostic, which microbe cannot reproduce on its own?"},{"heading":"The idea","text":"Microbes are organisms too small to see without a microscope. *Bacteria* are single cells without a nucleus (prokaryotes) that carry their own ribosomes and can divide on their own. *Fungi* — yeasts and molds — are cells with a nucleus (eukaryotes) that absorb nutrients from their surroundings. *Viruses* are not cells at all: they are genetic material (DNA or RNA) wrapped in protein, with no metabolism, so they can only copy themselves by hijacking a living host cell. Most microbes are harmless or helpful; a *pathogen* is the small minority that causes disease."},{"heading":"Worked example","text":"Strep throat is caused by *Streptococcus* bacteria — treatable with antibiotics that attack bacterial cell walls. Influenza is caused by a virus — antibiotics do nothing, because the virus has no bacterial machinery to attack. Athlete''s foot is a fungal infection, treated with antifungals. Same symptom category (infection), three very different culprits and treatments."},{"heading":"Your turn","text":"Classify each as bacterium, virus, or fungus: (1) a yeast causing a skin rash, (2) SARS-CoV-2, which needs your cells to replicate, (3) E. coli dividing in a broth on its own, (4) a mold growing on bread. Answers: (1) fungus, (2) virus, (3) bacterium, (4) fungus."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling every germ a ''bacteria'' — many infections are viral or fungal. Mistake: thinking all microbes are harmful — most are neutral or beneficial (your gut bacteria help digest food). Exit: (a) Which microbe has no metabolism of its own? (b) Are most microbes pathogens? Answers: viruses; no — most are harmless or helpful."}]}'::jsonb, 'Bacteria and fungi are cells; viruses are not — that difference drives everything else.', 12),
  (3, 'How infections spread', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the main routes of transmission and why the *chain of infection* can be broken at any link. Warm-up: name one everyday habit that stops germs from spreading."},{"heading":"The idea","text":"For disease to spread it needs a *chain of infection*: a pathogen, a reservoir (where it lives), a portal of exit, a route of transmission, a portal of entry, and a susceptible host. Transmission routes include *direct contact* (touch), *droplet* spread (coughing, sneezing over short distances), *airborne* spread (tiny particles that linger), *vehicle* spread (contaminated food or water), and *vector* spread (insects like mosquitoes). Breaking any single link — handwashing, clean water, masks, vaccination — stops the chain."},{"heading":"Worked example","text":"Cholera spreads when sewage contaminates drinking water (a water vehicle). You can attack the chain at several links: treat the water (route), improve sanitation (reservoir), or rehydrate and treat patients (susceptible host). Malaria, by contrast, spreads by mosquito bite (a vector), so bed nets break its chain instead."},{"heading":"Your turn","text":"Name the transmission route: (1) a flu virus in a sneeze reaching someone nearby, (2) undercooked contaminated chicken, (3) a tick bite passing Lyme disease, (4) shaking hands with someone who has a cold, then touching your eyes. Answers: (1) droplet, (2) vehicle/food, (3) vector, (4) direct/indirect contact."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking you must attack the pathogen itself to stop spread — often the easiest link to break is the route (clean water, masks, nets). Mistake: confusing droplet (short range) with airborne (lingering particles). Exit: (a) Name one link in the chain of infection. (b) Which route do mosquitoes represent? Answers: e.g. reservoir/route/host; vector."}]}'::jsonb, 'Transmission = how a pathogen gets from one host to the next. Break the route, stop the spread.', 11),
  (4, 'Innate immunity: barriers and inflammation', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe the body''s first-line barriers and explain what inflammation does. Warm-up: from the diagnostic, name the four classic signs of inflammation."},{"heading":"The idea","text":"*Innate immunity* is the defense you are born with: fast, general, and the same each time — it has no memory. Its first line is barriers: intact *skin*, mucous membranes, stomach acid, and enzymes in tears and saliva. If a pathogen breaks through, the second line kicks in: *phagocytes* (white blood cells like macrophages and neutrophils) engulf and digest invaders, and *inflammation* increases blood flow so more immune cells reach the site. The four signs of inflammation — redness, heat, swelling, and pain — are the visible result. Fever is another innate response that slows many pathogens."},{"heading":"Worked example","text":"You get a splinter. Bacteria enter through the broken skin (barrier breached). Local cells release signals that widen blood vessels; the area turns red, warm, and swollen. Neutrophils arrive and engulf the bacteria; the pus you may see is spent immune cells and debris. All of this happens within hours — no prior exposure needed, because innate immunity is ready from birth."},{"heading":"Your turn","text":"Innate or not? (1) skin blocking microbes, (2) a macrophage engulfing bacteria, (3) an antibody made specifically against measles, (4) fever, (5) swelling around a cut, (6) memory cells from a past infection. Answers: (1) innate, (2) innate, (3) not — adaptive, (4) innate, (5) innate, (6) not — adaptive."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating inflammation as purely bad — it is a normal, useful part of defense (though chronic inflammation can harm). Mistake: thinking innate immunity ''remembers'' — it doesn''t; that''s the adaptive system. Exit: (a) Does innate immunity have memory? (b) Name a phagocyte. Answers: no; macrophage or neutrophil."}]}'::jsonb, 'Innate = fast, general, no memory. It is the same response every time.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which microbe is NOT a living cell?","options":["bacterium","yeast","virus","mold"],"answer":2,"explanation":"Viruses are genetic material in a protein coat, not cells."},{"prompt":"Antibiotics are useless against the flu because the flu is caused by a…","options":["bacterium","virus","fungus","toxin"],"answer":1,"explanation":"Antibiotics target bacterial structures, not viruses."},{"prompt":"A mosquito passing a pathogen by biting is an example of … transmission.","options":["droplet","vehicle","vector","direct contact"],"answer":2,"explanation":"Insects that carry pathogens are vectors."},{"prompt":"Handwashing and clean water stop disease by breaking the…","options":["pathogen''s DNA","chain of infection","adaptive response","fever"],"answer":1,"explanation":"They break a link in the chain of infection (the route)."},{"prompt":"Which is a first-line barrier of innate immunity?","options":["a memory B cell","intact skin","a specific antibody","a vaccine"],"answer":1,"explanation":"Skin is a physical barrier and part of innate immunity."},{"prompt":"Redness, heat, swelling, and pain describe…","options":["antibody production","inflammation","immunological memory","antibiotic action"],"answer":1,"explanation":"These are the four classic signs of inflammation."}]}'::jsonb, null, 8),
  (6, 'Adaptive immunity: B cells, T cells, and antibodies', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Distinguish B cells from T cells and explain what antibodies do. Warm-up: which cells make antibodies?"},{"heading":"The idea","text":"*Adaptive immunity* is targeted and learned. It recognizes a specific molecular fingerprint on a pathogen called an *antigen*. Two lymphocytes do the work. *B cells* mature into *plasma cells* that secrete *antibodies* — Y-shaped proteins that lock onto a matching antigen, tagging or neutralizing the pathogen (this is the *humoral* response). *T cells* come in types: *helper T cells* coordinate the whole response by releasing signals, while *cytotoxic (killer) T cells* destroy the body''s own cells that have been infected by a virus (the *cell-mediated* response). The first exposure is slow (days to build up), but some B and T cells become long-lived *memory cells*."},{"heading":"Worked example","text":"A new virus infects you. Helper T cells recognize the antigen and sound the alarm. B cells specific to that antigen multiply and pour out antibodies that bind the virus and mark it for destruction. Cytotoxic T cells kill your own cells that the virus has already invaded, cutting off its factory. It takes about 1–2 weeks the first time — which is why a brand-new infection can make you sick before you recover."},{"heading":"Your turn","text":"Match the job to the cell: (1) secretes antibodies, (2) kills virus-infected body cells, (3) coordinates the response and activates others, (4) the Y-shaped protein that binds a specific antigen, (5) a long-lived cell that speeds up the next response. Options: plasma/B cell, cytotoxic T cell, helper T cell, antibody, memory cell. Answers: (1) plasma/B cell, (2) cytotoxic T cell, (3) helper T cell, (4) antibody, (5) memory cell."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking antibodies kill pathogens directly — they mostly neutralize or tag them so other cells finish the job. Mistake: mixing up B and T cells — B for antiBodies is a handy hook. Exit: (a) Which cell type makes antibodies? (b) What does a cytotoxic T cell do? Answers: B cells (plasma cells); it kills infected body cells."}]}'::jsonb, 'Adaptive = specific, slower the first time, and it remembers. B cells make antibodies; T cells coordinate and kill.', 13),
  (7, 'Vaccines and immune memory', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how immunological memory makes the second response faster, and how vaccines use it safely. Warm-up: why is a repeat infection often milder than the first?"},{"heading":"The idea","text":"After an adaptive response, most effector cells die off but a pool of *memory B and T cells* remains. On re-exposure to the same antigen, these memory cells trigger a *secondary response* that is faster and stronger — often clearing the pathogen before you feel sick. A *vaccine* exploits this by presenting a harmless form of the antigen: a weakened or inactivated microbe, a piece of it (a protein or sugar), or instructions to make that piece, such as an *mRNA vaccine* that has your cells briefly display the antigen. The vaccine cannot cause the disease, but it generates memory cells, so real infection meets an army that is already trained. When enough of a community is immune, spread slows and vulnerable people are protected — *herd immunity*."},{"heading":"Worked example","text":"An mRNA COVID-19 vaccine delivers instructions for the coronavirus''s harmless spike protein. Your cells display the spike; your immune system builds antibodies and memory cells against it. The mRNA is degraded within days and never enters the cell nucleus or alters your DNA. Later, if the real virus arrives, memory cells respond within hours to days instead of one to two weeks — the difference between a mild case and a serious one."},{"heading":"Your turn","text":"True or false, with a reason: (1) A vaccine gives you the disease it protects against. (2) The secondary response is faster than the first. (3) mRNA vaccines change your DNA. (4) Herd immunity protects people who can''t be vaccinated. Answers: (1) False — it uses a harmless antigen, not live disease-causing infection; (2) True — memory cells act fast; (3) False — mRNA is degraded and never enters the nucleus; (4) True — less spread shields the vulnerable."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing vaccines ''overload'' the immune system — you meet vastly more antigens daily from food and the environment than any vaccine contains. Mistake: thinking natural infection is always ''safer'' than a vaccine — infection carries the full risk of the disease, which vaccines avoid. Exit: (a) What cell type explains a faster second response? (b) Can a vaccine cause the disease it prevents? Answers: memory cells; no."}]}'::jsonb, 'A vaccine shows the immune system a harmless preview so memory is ready before the real pathogen arrives.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"pathogen","translation":"a microbe that causes disease","example":"Only a minority of microbes are pathogens; most are harmless or helpful."},{"term":"antigen","translation":"a molecular marker on a pathogen that the immune system recognizes","example":"Each antibody binds one specific antigen."},{"term":"antibody","translation":"a Y-shaped protein made by B cells that binds a specific antigen","example":"Antibodies neutralize or tag pathogens for destruction."},{"term":"inflammation","translation":"an innate response causing redness, heat, swelling, and pain","example":"Inflammation brings more immune cells to a wound."},{"term":"memory cell","translation":"a long-lived B or T cell that speeds up the response on re-exposure","example":"Memory cells make the secondary response faster and stronger."},{"term":"antimicrobial resistance","translation":"when microbes evolve so a drug that once killed them no longer works","example":"Overusing antibiotics drives antimicrobial resistance."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Antibodies are made by…","options":["cytotoxic T cells","B cells (plasma cells)","macrophages","red blood cells"],"answer":1,"explanation":"B cells mature into antibody-secreting plasma cells."},{"prompt":"A cytotoxic (killer) T cell mainly…","options":["makes antibodies","kills virus-infected body cells","forms the skin barrier","produces stomach acid"],"answer":1,"explanation":"Cytotoxic T cells destroy infected host cells."},{"prompt":"The secondary immune response is faster because of…","options":["antibiotics","memory cells","thicker skin","more stomach acid"],"answer":1,"explanation":"Memory B and T cells respond quickly on re-exposure."},{"prompt":"An mRNA vaccine works by…","options":["editing your DNA permanently","having cells briefly display a harmless antigen","injecting live virus","killing bacteria in the blood"],"answer":1,"explanation":"It provides instructions to display an antigen; the mRNA is soon degraded and never alters DNA."},{"prompt":"Antimicrobial resistance is driven largely by…","options":["vaccination","overuse and misuse of antibiotics","handwashing","fever"],"answer":1,"explanation":"Overuse selects for resistant microbes."},{"prompt":"Finishing a full prescribed antibiotic course when directed helps because…","options":["it makes the drug taste better","leftover partially resistant bacteria are less likely to survive and spread","it prevents all viruses","antibiotics build immune memory"],"answer":1,"explanation":"Following the prescribed regimen reduces the chance resistant survivors persist."}]}'::jsonb, null, 8),
  (10, 'Applied project: explain how a vaccine trains the immune system', 'writing', '{"sections":[{"heading":"The task","text":"Write a clear, accurate explanation — aimed at a curious friend with no biology background — of how a vaccine trains the immune system to fight a real pathogen. Use plain language, but get the science right."},{"heading":"Milestones","text":"1) Define antigen and antibody in one sentence each. 2) Describe what happens the first time the body meets a real pathogen (roles of B cells, helper T cells, and the 1–2 week delay). 3) Explain what a vaccine presents instead (a harmless antigen — weakened microbe, a protein piece, or mRNA instructions) and why it cannot cause the disease. 4) Explain memory cells and why the response to the real pathogen is then faster. 5) Add one sentence on herd immunity."},{"heading":"Self-check rubric","text":"✔ You correctly stated that a vaccine uses a harmless antigen, not a live disease-causing infection. ✔ You named memory cells as the reason the second response is faster. ✔ You avoided the myth that mRNA vaccines alter DNA (they don''t — the mRNA is degraded and never enters the nucleus). ✔ You explained herd immunity as reduced spread protecting the vulnerable. If all four are true, your explanation is both clear and scientifically sound."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000001b' and l.position = v.pos
);
